    juce::Image decodeImage (const char* data)
    {
        juce::MemoryOutputStream bytes;
        if (! juce::Base64::convertFromBase64 (bytes, data))
            return {};
        return juce::ImageFileFormat::loadFrom (bytes.getData(), bytes.getDataSize());
    }

    struct Finishes { juce::Image wood, panel; };

    const Finishes& finishes (int theme)
    {
        // Wood and powder coat are sampled from the three approved mockups.
        static const Finishes surfaces[] {
            { decodeImage (ashWood), decodeImage (ashPanel) },
            { decodeImage (walnutWood), decodeImage (walnutPanel) },
            { decodeImage (ivoryWood), decodeImage (ivoryPanel) }
        };
        return surfaces[theme];
    }

    juce::Image fadeEdge (const char* photo, bool acrossX)
    {
        auto edge = decodeImage (photo).convertedToFormat (juce::Image::ARGB);
        juce::Image::BitmapData pixels (edge, juce::Image::BitmapData::readWrite);
        const int end = (acrossX ? pixels.width : pixels.height) - 1;
        for (int y = 0; y < pixels.height; ++y)
            for (int x = 0; x < pixels.width; ++x)
            {
                const int at = acrossX ? x : y;
                const float alpha = juce::jlimit (0.0f, 1.0f, (float) juce::jmin (at, end - at) / 2.5f);
                pixels.setPixelColour (x, y, pixels.getPixelColour (x, y).withAlpha (alpha));
            }
        return edge;
    }

    void drawMainBezel (juce::Graphics& g, juce::Rectangle<int> bounds)
    {
        static const auto top = fadeEdge (topEdge, false);
        static const auto bottom = fadeEdge (bottomEdge, false);
        static const auto left = fadeEdge (leftEdge, true);
        static const auto right = fadeEdge (rightEdge, true);
        auto area = bounds.toFloat();
        g.setColour (juce::Colours::white);
        g.drawImage (left, area.removeFromLeft (15.0f));
        g.drawImage (right, area.removeFromRight (15.0f));
        g.drawImage (top, area.removeFromTop (14.0f).expanded (4.0f, 0.0f).translated (0.0f, -5.0f));
        g.drawImage (bottom, area.removeFromBottom (15.0f).expanded (4.0f, 0.0f));
    }

    struct KnobPhoto
    {
        juce::Image original, bronze;
        float pointerAngle, capRatio, diameter;
    };

    KnobPhoto makeKnobPhoto (const char* data, float angle, float capRatio, float diameter)
    {
        auto original = decodeImage (data);
        auto bronze = original.createCopy();
        juce::Image::BitmapData pixels (bronze, juce::Image::BitmapData::readWrite);
        for (int y = 0; y < pixels.height; ++y)
            for (int x = 0; x < pixels.width; ++x)
            {
                const auto c = pixels.getPixelColour (x, y);
                const auto luma = 0.24f * c.getFloatRed() + 0.68f * c.getFloatGreen() + 0.08f * c.getFloatBlue();
                pixels.setPixelColour (x, y, juce::Colour::fromFloatRGBA (
                    juce::jmin (1.0f, luma * 1.13f), luma * 0.90f, luma * 0.68f, c.getFloatAlpha()));
            }
        return { original, bronze, angle, capRatio, diameter };
    }

    const KnobPhoto& knobPhoto (bool compact, bool selector, bool frequency)
    {
        static const auto main = makeKnobPhoto (knobMain, 2.63f, 0.61f, 56.0f);
        static const auto choice = makeKnobPhoto (knobSelector, -0.33f, 0.46f, 58.0f);
        static const auto tuning = makeKnobPhoto (knobFrequency, 0.03f, 0.69f, 64.0f);
        static const auto small = makeKnobPhoto (knobSmall, -2.41f, 0.57f, 40.0f);
        return compact ? small : (selector ? choice : (frequency ? tuning : main));
    }

    const juce::Image& switchPhoto (bool on, bool vertical, bool blue, bool silver)
    {
        static const auto blueOnPhoto = decodeImage (blueOn);
        static const auto blueOffPhoto = decodeImage (blueOff);
        static const auto amberOnPhoto = decodeImage (amberOn);
        static const auto amberOffPhoto = decodeImage (amberOff);
        static const auto neutralPhoto = decodeImage (neutral);
        static const auto blueVerticalPhoto = decodeImage (blueVertical);
        static const auto amberVerticalPhoto = decodeImage (amberVertical);
        if (vertical)
            return blue ? blueVerticalPhoto : amberVerticalPhoto;
        if (silver)
            return neutralPhoto;
        return blue ? (on ? blueOnPhoto : blueOffPhoto) : (on ? amberOnPhoto : amberOffPhoto);
    }

    juce::Font panelFont (float size, bool bold = true, float kerning = 0.0f)
    {
        static const auto face = []
        {
            juce::MemoryOutputStream bytes;
            juce::Base64::convertFromBase64 (bytes, panelFontData);
            return juce::Typeface::createSystemTypefaceFor (bytes.getData(), bytes.getDataSize());
        }();
        const auto options = face != nullptr ? juce::FontOptions (face).withHeight (size)
                                             : juce::FontOptions (size, bold ? juce::Font::bold : juce::Font::plain);
        return juce::Font (options).withExtraKerningFactor (kerning * 0.35f);
    }

    juce::Font monoFont (float size)
    {
        return juce::Font (juce::FontOptions (juce::Font::getDefaultMonospacedFontName(), size, juce::Font::plain));
    }

    constexpr int editorW = 1400, editorH = 682, cheekW = 26, auxiliaryColumns = 11, auxiliaryRowHeight = 112;
    const juce::Identifier themeProperty { "panelTheme" };

